_CSV_GZIP_B64 = ""


def _typed_rows(csv_text):
    rows = list(csv.DictReader(StringIO(csv_text)))
    for row in rows:
        for key, value in row.items():
            if value == "":
                row[key] = None
            elif value in ("True", "False"):
                row[key] = value == "True"
            else:
                try:
                    row[key] = float(value) if "." in value else int(value)
                except ValueError:
                    pass
    return rows


def prepare_data():
    return pd.DataFrame(_typed_rows(decompress(b64decode(_CSV_GZIP_B64)).decode("utf-8")))


def _resolved(settings):
    values = {field["path"]: field["default"] for field in PLOT_SCHEMA}
    values.update(settings or {})
    return values


def _limits(values, lower_floor, upper_floor, padding):
    values = values.dropna()
    return min(lower_floor, float(values.min()) - padding), max(upper_floor, float(values.max()) + padding)


def _kde(axis, values, limits, color, orientation, line_width, fill_alpha, support_points):
    values = values.dropna().to_numpy()
    support = np.linspace(*limits, support_points)
    density = gaussian_kde(values)(support)
    if orientation == "horizontal":
        axis.plot(support, density, color=color, lw=line_width)
        axis.fill_between(support, 0, density, color=color, alpha=fill_alpha)
    else:
        axis.plot(density, support, color=color, lw=line_width)
        axis.fill_betweenx(support, 0, density, color=color, alpha=fill_alpha)


def render(data, settings):
    s = _resolved(settings)
    stable = data.loc[data["included_main_figure"]].copy()
    columns = ["outside_normalized", "other_science_normalized", "computer_science_normalized"]
    titles = s["axes.panel_titles"]
    x_limits = _limits(stable["home_normalized"], s["axes.x_min_floor"], s["axes.max_floor"], s["axes.limit_padding"])
    y_values = pd.concat([stable[column] for column in columns], ignore_index=True)
    y_limits = _limits(y_values, 0, s["axes.max_floor"], s["axes.limit_padding"])
    colors = {"AI": s["series.ai.color"], "Domain": s["series.domain.color"]}
    fig = plt.figure(figsize=s["figure.size"], facecolor=s["figure.facecolor"])
    outer = fig.add_gridspec(2, 3, left=s["layout.left"], right=s["layout.right"],
                             bottom=s["layout.bottom"], top=s["layout.top"],
                             wspace=s["layout.column_space"], hspace=s["layout.row_space"])
    for row, leader in enumerate(["AI", "Domain"]):
        group = stable.loc[stable["leader_class"].eq(leader)]
        for column_index, (y_column, title) in enumerate(zip(columns, titles)):
            ratio = s["layout.marginal_ratio"]
            inner = outer[row, column_index].subgridspec(
                4, 4, width_ratios=[1, 1, 1, ratio], height_ratios=[ratio, 1, 1, 1],
                hspace=s["layout.inner_space"], wspace=s["layout.inner_space"])
            ax_top = fig.add_subplot(inner[0, :3])
            ax = fig.add_subplot(inner[1:, :3])
            ax_right = fig.add_subplot(inner[1:, 3], sharey=ax)
            ax.scatter(group["home_normalized"], group[y_column], s=s["series.marker_size"],
                       color=colors[leader], edgecolor=s["series.marker_edge"],
                       linewidth=s["series.marker_edge_width"], alpha=s["series.alpha"], zorder=3)
            ax.set_xlim(*x_limits)
            ax.set_ylim(*y_limits)
            ax.axvline(s["reference.value"], color=s["reference.color"],
                       lw=s["reference.line_width"], ls="--")
            ax.axhline(s["reference.value"], color=s["reference.color"],
                       lw=s["reference.line_width"], ls="--")
            ax.xaxis.set_major_locator(MaxNLocator(nbins=s["axes.max_ticks"]))
            ax.yaxis.set_major_locator(MaxNLocator(nbins=s["axes.max_ticks"]))
            ax.spines["top"].set_visible(False)
            ax.spines["right"].set_visible(False)
            for spine in ax.spines.values():
                spine.set_linewidth(s["axes.spine_width"])
            ax.tick_params(direction="out", labelsize=s["typography.tick_label_size"])
            if column_index == 1:
                ax.set_xlabel(s["axes.x_label"], fontsize=s["typography.axis_label_size"])
            if column_index == 0:
                ax.set_ylabel(s["axes.y_label"], fontsize=s["typography.axis_label_size"])
            if row == 0:
                ax_top.set_title(title, fontsize=s["typography.title_size"], pad=s["typography.title_pad"])
            _kde(ax_top, group["home_normalized"], x_limits, colors[leader], "horizontal",
                 s["kde.line_width"], s["kde.fill_alpha"], s["kde.support_points"])
            _kde(ax_right, group[y_column], y_limits, colors[leader], "vertical",
                 s["kde.line_width"], s["kde.fill_alpha"], s["kde.support_points"])
            ax_top.set_xlim(*x_limits)
            ax_right.set_ylim(*y_limits)
            ax_top.set_xticks([])
            ax_top.set_yticks([])
            ax_right.set_xticks([])
            ax_right.tick_params(axis="y", left=False, right=False, labelleft=False, labelright=False)
            for marginal in (ax_top, ax_right):
                for spine in marginal.spines.values():
                    spine.set_visible(False)
            if column_index == 0:
                group_label = s["annotation.group_labels"][row]
                ax.text(*s["annotation.position"], group_label, transform=ax.transAxes,
                        ha="left", va="bottom", color=colors[leader],
                        fontsize=s["typography.group_label_size"], fontweight="bold")
    for item in fig.findobj(match=Text):
        item.set_fontfamily(s["typography.font_family"])
    return fig
